/**
 * Bit-exact parity with the Rust program math. vectors.json is generated by
 * `cargo test -p groundgraph --lib parity` from programs/groundgraph/src/math.rs; u64 values are decimal strings.
 */
import { describe, expect, it } from 'vitest';
import vectors from './vectors.json';
import {
  GgMathError,
  comparePrice,
  feeBpsNow,
  feeCeil,
  isqrt,
  ceilSqrt,
  lpPayout,
  priceBps,
  quoteBuy,
  quoteSell,
  seedReserves,
  updateEma,
  voidLpClaim,
  MAX_RESERVE,
  MIN_TRADE_USDC,
  MIN_SELL_GROSS_USDC,
  P0_MAX_BPS,
  P0_MIN_BPS,
  priceAbove,
} from '../src/index';

const B = (s: string): bigint => BigInt(s);

function thrownCode(fn: () => unknown): string | null {
  try {
    fn();
    return null;
  } catch (e) {
    if (e instanceof GgMathError) return e.code;
    throw e;
  }
}

describe('vectors metadata', () => {
  it('has the expected size and constants', () => {
    expect(vectors.version).toBe(1);
    expect(vectors.quoteBuy.length + vectors.quoteSell.length).toBeGreaterThanOrEqual(2000);
    expect(B(vectors.constants.maxReserve)).toBe(MAX_RESERVE);
    expect(B(vectors.constants.minTradeUsdc)).toBe(MIN_TRADE_USDC);
    expect(B(vectors.constants.minSellGrossUsdc)).toBe(MIN_SELL_GROSS_USDC);
    expect(vectors.constants.p0MinBps).toBe(P0_MIN_BPS);
    expect(vectors.constants.p0MaxBps).toBe(P0_MAX_BPS);
  });
});

describe('quoteBuy parity', () => {
  it('matches every vector', () => {
    let ok = 0;
    let errs = 0;
    for (const c of vectors.quoteBuy) {
      const pool = { reserveAbove: B(c.ra), reserveBelow: B(c.rb) };
      const side = c.side as 'above' | 'below';
      if ('error' in c) {
        expect(thrownCode(() => quoteBuy(pool, side, B(c.usdcIn), c.feeBps)), JSON.stringify(c)).toBe(c.error);
        errs++;
        continue;
      }
      const q = quoteBuy(pool, side, B(c.usdcIn), c.feeBps);
      const o = c.out!;
      expect(q.sharesOut, JSON.stringify(c)).toBe(B(o.sharesOut));
      expect(q.feeUsdc).toBe(B(o.feeUsdc));
      expect(q.usdcIntoSets).toBe(B(o.usdcIntoSets));
      expect(q.poolAfter.reserveAbove).toBe(B(o.ra));
      expect(q.poolAfter.reserveBelow).toBe(B(o.rb));
      expect(q.priceImpactBps).toBe(o.impactBps);
      expect(Math.round(q.priceAfter * 10_000)).toBe(o.priceAfterBps);
      expect(Math.round(q.priceBefore * 10_000)).toBe(o.priceBeforeBps);
      ok++;
    }
    expect(ok).toBeGreaterThan(1000);
    expect(errs).toBeGreaterThan(0);
  });
});

describe('quoteSell parity', () => {
  it('matches every vector', () => {
    let ok = 0;
    let errs = 0;
    for (const c of vectors.quoteSell) {
      const pool = { reserveAbove: B(c.ra), reserveBelow: B(c.rb) };
      const side = c.side as 'above' | 'below';
      if ('error' in c) {
        expect(thrownCode(() => quoteSell(pool, side, B(c.sharesIn), c.feeBps)), JSON.stringify(c)).toBe(c.error);
        errs++;
        continue;
      }
      const q = quoteSell(pool, side, B(c.sharesIn), c.feeBps);
      const o = c.out!;
      expect(q.usdcGross, JSON.stringify(c)).toBe(B(o.usdcGross));
      expect(q.usdcOut).toBe(B(o.usdcOut));
      expect(q.feeUsdc).toBe(B(o.feeUsdc));
      expect(q.poolAfter.reserveAbove).toBe(B(o.ra));
      expect(q.poolAfter.reserveBelow).toBe(B(o.rb));
      expect(q.priceImpactBps).toBe(o.impactBps);
      expect(Math.round(q.priceAfter * 10_000)).toBe(o.priceAfterBps);
      ok++;
    }
    expect(ok).toBeGreaterThan(500);
    expect(errs).toBeGreaterThan(0);
  });
});

describe('small functions parity', () => {
  it('feeCeil', () => {
    for (const c of vectors.feeCeil) expect(feeCeil(B(c.amount), c.bps), JSON.stringify(c)).toBe(B(c.out));
  });
  it('priceBps', () => {
    for (const c of vectors.priceBps) {
      expect(priceBps({ reserveAbove: B(c.ra), reserveBelow: B(c.rb) }), JSON.stringify(c)).toBe(c.out);
    }
  });
  it('isqrt and ceilSqrt', () => {
    for (const c of vectors.isqrt) {
      expect(isqrt(B(c.n)), c.n).toBe(B(c.floor));
      expect(ceilSqrt(B(c.n)), c.n).toBe(B(c.ceil));
    }
  });
  it('seedReserves', () => {
    let errs = 0;
    for (const c of vectors.seedReserves) {
      if ('error' in c) {
        expect(thrownCode(() => seedReserves(B(c.liquidity), c.p0Bps)), JSON.stringify(c)).toBe(c.error);
        errs++;
        continue;
      }
      const r = seedReserves(B(c.liquidity), c.p0Bps);
      expect(r.reserveAbove).toBe(B(c.out!.ra));
      expect(r.reserveBelow).toBe(B(c.out!.rb));
      expect(r.creatorAbove).toBe(B(c.out!.creatorAbove));
      expect(r.creatorBelow).toBe(B(c.out!.creatorBelow));
    }
    expect(errs).toBeGreaterThan(0);
  });
  it('updateEma', () => {
    for (const c of vectors.updateEma) expect(updateEma(c.ema, c.emaTs, c.impact, c.now), JSON.stringify(c)).toBe(c.out);
  });
  it('feeBpsNow', () => {
    for (const c of vectors.feeBpsNow) {
      const r = feeBpsNow(
        { baseFeeBps: c.baseFeeBps, dynamicFee: c.dynamicFee, emaImpactBps: c.emaImpactBps, emaTs: c.emaTs, settleTs: c.settleTs, maxFeeBps: c.maxFeeBps },
        c.now,
      );
      expect(r, JSON.stringify(c)).toEqual(c.out);
    }
  });
  it('voidLpClaim', () => {
    for (const c of vectors.voidLpClaim) {
      expect(voidLpClaim(B(c.completeSets), { reserveAbove: B(c.ra), reserveBelow: B(c.rb) }, B(c.feePool)), JSON.stringify(c)).toBe(B(c.out));
    }
  });
  it('lpPayout', () => {
    for (const c of vectors.lpPayout) expect(lpPayout(B(c.claim), B(c.lpAmount), B(c.lpSupply)), JSON.stringify(c)).toBe(B(c.out));
  });
  it('comparePrice', () => {
    let errs = 0;
    for (const c of vectors.comparePrice) {
      if ('error' in c) {
        expect(thrownCode(() => comparePrice(B(c.price), c.expo, B(c.target), c.targetExpo))).toBe(c.error);
        errs++;
        continue;
      }
      expect(comparePrice(B(c.price), c.expo, B(c.target), c.targetExpo), JSON.stringify(c)).toBe(c.out);
    }
    expect(errs).toBeGreaterThan(0);
  });
  it('priceAbove is priceBps / 10000', () => {
    expect(priceAbove({ reserveAbove: 1n, reserveBelow: 1n })).toBe(0.5);
  });
});
